<?php
namespace App\Http\Controllers;
use App\Models\{Venue,MetaConnection};use App\Services\ConversationService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
class MessagingController extends Controller {
 private function own(Request $r,Venue $v){abort_unless($v->owner_account_id===$r->user()->id,403);}
 public function connections(Request $r,Venue $venue){$this->own($r,$venue);return MetaConnection::where('venue_id',$venue->id)->get()->map(fn($c)=>$this->data($c,$venue));}
 private function data(MetaConnection $c,Venue $v):array{return array_merge($c->toArray(),['version'=>$c->credentials['version']??'v26.0','configured'=>array_keys(array_filter($c->credentials??[])),'webhook_url'=>rtrim(config('portal.customer_url'),'/').'/api/meta/webhooks/'.$v->slug.'/'.$c->channel]);}
 public function save(Request $r,Venue $venue,string $channel){$this->own($r,$venue);abort_unless(in_array($channel,['whatsapp','instagram','facebook']),404);$d=$r->validate(['account_id'=>'required|regex:/^[0-9]{1,100}$/','enabled'=>'required|boolean','auto_reply'=>'required|boolean','access_token'=>'nullable|string|max:5000','app_secret'=>'nullable|string|max:500','verify_token'=>'nullable|string|min:16|max:200','version'=>'required|regex:/^v[0-9]{2}\.0$/']);$c=MetaConnection::firstOrNew(['venue_id'=>$venue->id,'channel'=>$channel]);$credentials=$c->credentials??[];foreach(['access_token','app_secret','verify_token'] as $k)if(filled($d[$k]??null))$credentials[$k]=$d[$k];$credentials['version']=$d['version'];if($d['enabled'])foreach(['access_token','app_secret','verify_token'] as $k)abort_unless(filled($credentials[$k]??null),422,'Completa token de acceso, secreto de aplicación y token de verificación.');if($c->exists&&$c->account_id!==$d['account_id'])abort_if(DB::table('message_threads')->where('meta_connection_id',$c->id)->exists(),422,'Esta cuenta tiene conversaciones. Conserva su identificador para proteger el historial.');$c->fill(collect($d)->only(['account_id','enabled','auto_reply'])->all());$c->credentials=$credentials;$c->save();return $this->data($c,$venue);}
 public function inbox(Request $r,Venue $venue){$this->own($r,$venue);return DB::table('message_threads')->where('venue_id',$venue->id)->orderByDesc('updated_at')->paginate(30);}
 public function messages(Request $r,Venue $venue,int $thread){$this->own($r,$venue);$t=DB::table('message_threads')->where('venue_id',$venue->id)->find($thread);abort_unless($t,404);$ids=DB::table('message_threads')->where('venue_id',$venue->id)->where('message_contact_id',$t->message_contact_id)->pluck('id');return DB::table('thread_messages')->join('message_threads','message_threads.id','=','thread_messages.message_thread_id')->whereIn('message_thread_id',$ids)->select('thread_messages.*','message_threads.channel')->orderByDesc('thread_messages.id')->paginate(60);}
 public function pause(Request $r,Venue $venue,int $thread){$this->own($r,$venue);$d=$r->validate(['paused'=>'required|boolean']);abort_unless(DB::table('message_threads')->where('venue_id',$venue->id)->where('id',$thread)->exists(),404);DB::table('message_threads')->where('id',$thread)->update(['paused'=>$d['paused'],'updated_at'=>now()]);return ['ok'=>true];}
 public function link(Request $r,Venue $venue,ConversationService $service){abort_unless($venue->published,404);$t=$service->webThread($venue,'u:'.$r->user()->id,$r->user()->id);$code=strtoupper(Str::random(24));DB::table('contact_links')->where('message_contact_id',$t->message_contact_id)->whereNull('used_at')->update(['expires_at'=>now()]);DB::table('contact_links')->insert(['message_contact_id'=>$t->message_contact_id,'token_hash'=>hash('sha256',$code),'expires_at'=>now()->addMinutes(10),'created_at'=>now(),'updated_at'=>now()]);return ['code'=>$code,'instruction'=>'Envía VINCULAR '.$code.' por mensaje privado al negocio en la red que quieras conectar. Caduca en 10 minutos y se usa una vez.'];}
 public function history(Request $r,Venue $venue,ConversationService $service){abort_unless($venue->published,404);$t=$service->webThread($venue,'u:'.$r->user()->id,$r->user()->id);$ids=DB::table('message_threads')->where('venue_id',$venue->id)->where('message_contact_id',$t->message_contact_id)->pluck('id');return DB::table('thread_messages')->join('message_threads','message_threads.id','=','thread_messages.message_thread_id')->whereIn('message_thread_id',$ids)->whereNotIn('status',['pending','sending','failed','unknown'])->select('thread_messages.id','direction','body','message_threads.channel','thread_messages.created_at')->latest('thread_messages.id')->limit(40)->get()->reverse()->values();}
}
